package br.com.admeclesial.application.relatorio;
import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.infrastructure.persistence.organizacao.OrganizacaoEclesialRepository; import br.com.admeclesial.infrastructure.persistence.pessoa.PessoaRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Set;
@Service public class RelatorioPessoaApplicationService { private static final Set<String> ORDENACOES=Set.of("nome","dataCadastro"); private final PessoaRepository pessoas; private final OrganizacaoEclesialRepository organizacoes; private final SegurancaOrganizacaoService seguranca;
 public RelatorioPessoaApplicationService(PessoaRepository p,OrganizacaoEclesialRepository o,SegurancaOrganizacaoService s){pessoas=p;organizacoes=o;seguranca=s;}
 @Transactional(readOnly=true) public RelatorioPagina<RelatorioPessoaItem> consultar(RelatorioPessoaFiltro f){ if(f.organizacaoUuid()==null)throw new IllegalArgumentException("Organização é obrigatória para o relatório"); seguranca.validarAcesso(f.organizacaoUuid()); var org=organizacoes.findByUuid(f.organizacaoUuid()).orElseThrow(); String ord=ORDENACOES.contains(f.ordenacao())?f.ordenacao():"nome"; int pag=Math.max(f.pagina(),0), tam=Math.min(Math.max(f.tamanho(),10),100); var dir="desc".equalsIgnoreCase(f.direcao())?Sort.Direction.DESC:Sort.Direction.ASC; String nome=f.nome()==null||f.nome().isBlank()?null:f.nome().trim(); var r=pessoas.pesquisarRelatorio(f.organizacaoUuid(),nome,f.ativo(),PageRequest.of(pag,tam,Sort.by(dir,ord))); var itens=r.getContent().stream().map(p->new RelatorioPessoaItem(p.getUuid(),p.getNome(),p.getNomeSocial(),p.getCpf(),p.getEmail(),p.isAtivo(),org.getNome())).toList(); return new RelatorioPagina<>(itens,pag,tam,r.getTotalElements(),r.getTotalPages(),ord,dir.name().toLowerCase()); }
}
